        async function cargarProximosPartidosPorFecha() {
            let fechaInicio = $("#fecha-inicio").val();
            let fechaFin = $("#fecha-fin").val();
            const { clubId, equipoId, seccion, delegacionKey } = obtenerIdsDeUrl();

            let datos = [];
            let intentos = 0;
            const maxIntentos = 52; // 52 semanas hacia atrás máximo

            // Bucle hasta encontrar al menos 10 registros
            while (datos.length < 10 && intentos < maxIntentos) {
                try {
                    const response = await $.ajax({
                        url: `/${delegacionKey}/fixture?handler=ProximosPartidos&fechaInicio=${fechaInicio}&fechaFin=${fechaFin}`,
                        type: 'GET',
                        contentType: "application/json; charset=utf-8"
                    });

                    const tempDiv = $('<div>').html(response);
                    const filas = tempDiv.find('tr').length - 1; // -1 para excluir header si existe

                    if (filas >= 10) {
                        // Encontramos suficientes datos
                        $('#proximosPartidos').html(response);
                        break;
                    } else {
                        // No hay suficientes datos, retroceder un mes
                        const fechaInicioDate = new Date(fechaInicio);
                        fechaInicioDate.setDate(fechaInicioDate.getDate() - 30);
                        fechaInicio = fechaInicioDate.toISOString().split('T')[0];

                        // Actualizar el campo visual para que el usuario vea el cambio
                        $("#fecha-inicio").val(fechaInicio);

                        intentos++;

                        // Si es el último intento exitoso o encontramos algunos datos, mostrarlos
                        if (intentos >= maxIntentos || filas > 8) {
                            $('#proximosPartidos').html(response);
                            break;
                        }
                    }
                } catch (xhr) {
                    console.error('Error:', xhr.responseText || xhr.statusText);
                    $('#proximosPartidos').html('<p>Error al cargar los datos</p>');
                    break;
                }
            }
        }

        function obtenerIdsDeUrl() {
            // /laliga/equipo/1930/55333
            const pathSegments = window.location.pathname.split('/');

            const delegacionKey = pathSegments[1]
            const clubId = parseInt(pathSegments[3], 10);   // 1930
            const equipoId = parseInt(pathSegments[4], 10); // 55333
            const seccion = pathSegments[5]; // 55333

            return { clubId, equipoId, seccion, delegacionKey };
        }

