    if ($("header").hasClass(".contenidoCabecera")) {
        if ($("#menuEscritorio").offset().top > $(".contenidoCabecera").height()) {
            posicionMenuEscritorio = $("#menuEscritorio").offset().top;
        } else {
            posicionMenuEscritorio = $(".contenidoCabecera").height();
