function ObtenerTamanoImgUrl(imageUrl) {
    return new Promise((resolve, reject) => {
        // 1. Crear un objeto Image en memoria.
        const img = new Image();

        // 2. Manejar la carga exitosa de la imagen
        img.onload = function () {
            const width = img.naturalWidth;
            const height = img.naturalHeight;

            // 3. Crear/Actualizar la meta etiqueta og:image:width
            updateMetaTag('og:image:width', width.toString());

            // 4. Crear/Actualizar la meta etiqueta og:image:height
            updateMetaTag('og:image:height', height.toString());

            resolve({ width, height });
        };

        // 5. Manejar errores de carga (por ejemplo, URL inválida o imagen corrupta)
        img.onerror = function () {
            reject(`Error al cargar la imagen desde la URL: ${imageUrl}`);
        };

        // 6. Iniciar la carga de la imagen
        img.src = imageUrl;
    });
};

function updateMetaTag(propertyName, content) {
    // Buscar una etiqueta existente con el mismo atributo 'property'
    let tag = document.querySelector(`meta[property='${propertyName}']`);

    if (!tag) {
        // Si no existe, crear una nueva
        tag = document.createElement('meta');
        tag.setAttribute('property', propertyName);
        document.head.appendChild(tag);
    }

    // Actualizar el valor del contenido
    tag.setAttribute('content', content);
}

