        // Función: Cargar grupos y seleccionar la primera, luego enviar
        function obtenerGrupos(faseId) {
            if (!faseId || faseId <= 0) return;

            $.get(`/api/clasificacion/${faseId}/grupos`, function (data) {
                let options = '';
                data.forEach(function (grupo, index) {
                    options += `<option value="${grupo.idGrupo}">${grupo.nombre}</option>`;
                });

                $("#select-grupo").html(options);
                const primerGrupo = $("#select-grupo option:eq(0)").val();
                if (primerGrupo) {
                    $("#select-grupo").val(primerGrupo);
                    enviarForm();
                }
            });
        }

      
        // Enviar formulario
        function enviarForm() {
            const grupo = $("#select-grupo").val();
            if (!grupo || grupo <= 0) return;

            enviarClasificacion();
        }


        function enviarClasificacion() {
            const faseId = $('#select-fase').val();
            const grupoId = $('#select-grupo').val();

            if (!grupoId || grupoId <= 0) return;

            let delegacionKey = 'laliga';

            $.ajax({
                url: `/${delegacionKey}/tabla-posiciones?handler=Clasificacion&faseId=${faseId}&grupoId=${grupoId}`,
